 const canvasFields:CanvasField[]=tool==='sketch'&&sketchEntities?[]:tool==='sketch'?(sketchProfile==='circle'?[{key:'width',label:'Diameter',value:fields.width,unit:doc?.unit}]:[{key:'width',label:'Width',value:fields.width,unit:doc?.unit},{key:'height',label:'Height',value:fields.height,unit:doc?.unit}])
 :tool==='extrude'?[...(extent==='blind'||extent==='two-sided'?[{key:'distance',label:'Distance',value:fields.distance,unit:doc?.unit}]:[]),...(extent==='two-sided'?[{key:'secondDistance',label:'Second depth',value:fields.secondDistance,unit:doc?.unit}]:[]),{key:'startOffset',label:'Start offset',value:fields.startOffset,unit:doc?.unit}]:tool==='fillet'?[{key:'radius',label:'Radius',value:fields.radius,unit:doc?.unit}]:tool&&isAdvanced(tool)?toolFields[tool].filter(f=>['length','number','angle'].includes(f.kind)&&!(tool==='hole'&&(!holeFieldActive(f.key,advanced)||advanced.termination==='through-all'&&f.key==='depth'||advanced.profileId&&['x','y','diameter'].includes(f.key)))).map(f=>({key:f.key,label:f.label,value:advanced[f.key]??'',unit:f.kind==='length'?doc?.unit:f.kind==='angle'?'deg':undefined})):[]
