 useEffect(()=>{
  const handler=(e:KeyboardEvent)=>{
   const target=e.target as HTMLElement
   if(document.querySelector('dialog[open]')||target.closest('[role="menu"],select,option'))return
   if(e.key==='Tab'&&!editor.busy&&!target.matches('input,textarea,select')&&tool&&!pickingSketchFace){if(tool!=='sketch'&&viewport.current?.focusValue()){e.preventDefault();return}if(canvasFields.length){e.preventDefault();canvasInputs.current?.focus();return}}
   if(e.key==='Escape'){e.preventDefault();cancel();editor.select(null);return}
   if(target.matches('input,textarea,select')||target.isContentEditable)return
   const mod=e.ctrlKey||e.metaKey
   if(mod&&e.key.toLowerCase()==='k'){e.preventDefault();setSearch(true);return}
   if(e.altKey)return
   const id=shortcutCommand(e.key,mod,e.shiftKey);if(id){e.preventDefault();run(id)}
  };window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler)
 })
