    {dimensionAxis&&<Dialog title="Edit sketch dimension" onClose={()=>setDimensionAxis(null)}><form onSubmit={e=>{e.preventDefault();try{const value=UnitService.parse(dimensionValue,doc.unit);if(value<.001||value>100000)throw Error('Dimension must be between 0.001 and 100000 mm.');field(dimensionAxis,String(UnitService.fromInternal(value,doc.unit)));setDimensionAxis(null)}catch(e){setError(String(e))}}}><label className="field"><span>{dimensionAxis==='width'?(sketchProfile==='circle'?'Diameter':'Width'):'Height'} · {doc.unit}</span><input aria-label="Dimension value" autoFocus value={dimensionValue} onChange={e=>setDimensionValue(e.target.value)}/></label>{error&&<p role="alert">{error}</p>}<div className="dialog-actions"><button type="button" className="button" onClick={()=>setDimensionAxis(null)}>Cancel</button><button className="button button-dark" type="submit">Set dimension</button></div></form></Dialog>}
